using System;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Windows.Forms;
namespace Stackshot
{
    internal static class BoardTests
    {
        static Bitmap Image(int width,int height,Color color){var image=new Bitmap(width,height);using(var g=Graphics.FromImage(image))g.Clear(color);return image;}
        static string Hash(Bitmap image){using(var memory=new MemoryStream()){image.Save(memory,System.Drawing.Imaging.ImageFormat.Png);using(var sha=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(memory.ToArray()));}}
        internal static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("board/ten independent resources export all content including negative and offscreen positions",delegate{using(var document=new BoardDocument()){for(int i=0;i<10;i++)document.AddImage(Image(120,80,Color.FromArgb(255,20*i,80,140)),new PointF(-300+(i%5)*150,-200+(i/5)*110));using(var image=document.Render()){check(document.Items.Length==10&&image.Size==new Size(720,190),"viewport-clipped export");check(image.GetPixel(20,20).ToArgb()==Color.FromArgb(255,0,80,140).ToArgb(),"first resource absent");check(image.GetPixel(700,170).ToArgb()==Color.FromArgb(255,180,80,140).ToArgb(),"last resource absent");image.Save(Path.Combine(output,"board-ten-images-export.png"));}}});
            run("board/duplicate shares immutable source but position layer rotation undo stay independent",delegate{using(var document=new BoardDocument()){string a=document.AddImage(Image(80,40,Color.Red),PointF.Empty);string b=document.AddImage(Image(80,40,Color.Blue),PointF.Empty);using(var image=document.Render())check(image.GetPixel(20,20).B==255,"layer order");document.Reorder(a,1);using(var image=document.Render())check(image.GetPixel(20,20).R==255,"raise layer");document.Undo();using(var image=document.Render())check(image.GetPixel(20,20).B==255,"layer undo");string copy=document.Duplicate(a);document.Change(copy,delegate(BoardItem item){item.X=200;item.Scale=2;item.Turns=1;});check(document.Bounds(document.Find(copy)).Size==new SizeF(80,160)&&document.Find(a).X==0&&document.Find(a).Turns==0,"transform leaked");document.Delete(b);document.Undo();check(document.Items.Length==3,"delete undo");document.Redo();check(document.Items.Length==2,"delete redo");}});
            run("board/project roundtrip embeds image resources and matches exact exported pixels",delegate{using(var document=new BoardDocument()){string id=document.AddImage(Image(100,60,Color.FromArgb(180,255,40,70)),new PointF(-40,50));document.Change(id,delegate(BoardItem item){item.Turns=1;item.Scale=.75f;});document.SetBackground(Color.FromArgb(240,245,250));string path=Path.Combine(output,"建筑参考图.scboard");document.Save(path);check(!document.Dirty,"save dirty");using(var loaded=BoardDocument.Open(path))using(var actual=loaded.Render())using(var expected=document.Render()){check(loaded.Items.Length==1&&loaded.Items[0].Id==id&&!loaded.Dirty,"project ids/clean");check(Hash(actual)==Hash(expected),"project pixels");loaded.Change(id,delegate(BoardItem item){item.X+=20;});check(loaded.Dirty,"edit not dirty");loaded.Undo();check(!loaded.Dirty,"undo saved state still dirty");}}});
            run("board/snap aligns edges and centers with a zoom-scaled tolerance",delegate{float? x,y;var point=BoardSnap.Move(new RectangleF(197,103,100,80),new[]{new RectangleF(20,100,180,80)},8,out x,out y);check(point.Y==100&&y==100&&x.HasValue,"snap lines");point=BoardSnap.Move(new RectangleF(240,400,100,80),new[]{new RectangleF(200,100,180,80)},2,out x,out y);check(point.X==240&&x==290&&!y.HasValue,"center snap");});
            run("board/production drag resize keys pan zoom and capture interruption preserve undo",delegate{using(var document=new BoardDocument())using(var owner=new Form())using(var view=new BoardView(document){Size=new Size(800,600)}){owner.Controls.Add(view);string id=document.AddImage(Image(100,60,Color.Red),PointF.Empty);view.Pan=new PointF(40,40);view.PointerDown(new Point(60,60),false);view.PointerMove(new Point(90,80),true);view.PointerUp();check(document.Find(id).X==30&&document.Find(id).Y==20,"drag");document.Undo();check(document.Find(id).X==0,"gesture undo");view.SelectedId=id;view.ApplyKey(Keys.Shift|Keys.Right);check(document.Find(id).X==10,"key move");var rect=view.ScreenBounds(document.Find(id));view.PointerDown(new Point((int)rect.Right-1,(int)rect.Bottom-1),false);view.PointerMove(new Point((int)rect.Right+49,(int)rect.Bottom+29),true);view.PointerUp();check(Math.Abs(document.Find(id).Scale-1.5f)<.05,"proportional resize");Point anchor=new Point(400,300);var before=view.World(anchor);view.ZoomAt(1.4f,anchor);var after=view.World(anchor);check(Math.Abs(before.X-after.X)<.001&&Math.Abs(before.Y-after.Y)<.001,"zoom anchor");view.PointerDown(new Point(20,20),true);view.PointerMove(new Point(60,40),true);view.PointerUp();check(!view.Visible,"view showed desktop");view.Fit();using(var image=new Bitmap(800,600)){view.DrawToBitmap(image,view.ClientRectangle);image.Save(Path.Combine(output,"board-view-offscreen.png"));}}});
            run("board/invalid project resource IDs and oversized export are rejected without source mutation",delegate{string path=Path.Combine(output,"board-invalid.scboard");using(var file=new FileStream(path,FileMode.Create,FileAccess.Write))using(var archive=new ZipArchive(file,ZipArchiveMode.Create))using(var writer=new StreamWriter(archive.CreateEntry("board.json").Open()))writer.Write("{\"Version\":1,\"Items\":[{\"Id\":\"../outside\",\"Resource\":\"../outside\"}]}");bool rejected=false;try{using(var doc=BoardDocument.Open(path)){};}catch(InvalidDataException){rejected=true;}check(rejected,"path traversal accepted");using(var doc=new BoardDocument()){string a=doc.AddImage(Image(20,20,Color.Blue),PointF.Empty);doc.AddImage(Image(20,20,Color.Red),new PointF(90000,90000));rejected=false;try{using(var image=doc.Render()){};}catch(InvalidOperationException){rejected=true;}check(rejected,"enormous export accepted");doc.Change(a,delegate(BoardItem item){item.Turns=3;});using(var image=doc.RenderItem(a))check(image.Size==new Size(20,20),"single item export uses whole board");}});
            run("board/hidden window paste and selected pin execute production adapters without desktop clipboard",delegate{using(var window=new BoardWindow()){window.ReadClipboard=delegate{return Image(80,50,Color.Coral);};int pins=0;window.PinImage=delegate(Bitmap image){pins++;check(image.Size==new Size(80,50),"pin dimensions");image.Dispose();};window.Paste();window.PinSelected();check(window.Document.Items.Length==1&&pins==1&&!window.Visible,"adapter did not route");window.PerformLayout();using(var image=new Bitmap(window.ClientSize.Width,window.ClientSize.Height)){using(var g=Graphics.FromImage(image))PreferencesPreview.Draw(g,window,window);image.Save(Path.Combine(output,"board-window-offscreen.png"));}}});
        }
    }
}
